<script setup lang="ts">import{onMounted,ref}from'vue';import{adminApi}from'../api';import{type WmNews}from'@leadnews/shared';const rows=ref<WmNews[]>([]),loading=ref(true);onMounted(async()=>{try{rows.value=(await adminApi.pending()).records}finally{loading.value=false}})</script><template><section class="panel"><div class="toolbar"><div style="flex:1"><p class="eyebrow">MANUAL REVIEW</p><h1>待人工审核</h1></div><el-tag type="warning">{{rows.length}} 条待处理</el-tag></div><el-table :data="rows" v-loading="loading"><el-table-column prop="title" label="标题" min-width="240"/><el-table-column prop="authorName" label="作者" width="130"/><el-table-column prop="submittedTime" label="提交时间" width="180"/><el-table-column label="审核信号" min-width="220"><template #default="{row}">{{row.reason||'需要人工判断'}}<p class="meta">{{row.auditSource}}</p></template></el-table-column><el-table-column width="100"><template #default="{row}"><RouterLink :to="`/audit/${row.id}`"><el-button text>审核</el-button></RouterLink></template></el-table-column></el-table><div v-if="!loading&&!rows.length" class="empty">暂无待审核稿件</div></section></template>
